private void sendHandshakePacket(NettyClientConnection nettyClientConnection) {
    HandshakeData handshakeData = new HandshakeData();
    handshakeData.clientId = nettyClientConnection.getClientId();
    handshakeData.serverTime = System.currentTimeMillis();
    handshakeData.needAuth = this.authStrategy != null;
    handshakeData.rsaPublicKey = nettyClientConnection.getRsaPublicKeyBase64();
    nettyClientConnection.send(WsMessage.create(WsMessage.TYPE_HANDSHAKE, handshakeData));
}
